3	import java.time.LocalDate;
4	import java.util.Collection;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Counts owners registered on a given day, compared by registrationDate.
10	 * Used to enforce the daily create limit.
11	 */
12	final class DailyRegistrations {
13	
14	    private DailyRegistrations() {
15	    }
16	
17	    /** Count existing owners whose registrationDate is the given day. */
18	    static int countOn(Collection<Owner> existing, LocalDate day) {
19	        return (int) existing.stream().filter(o -> day.equals(o.getRegistrationDate())).count();
20	    }
21	}
