16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    public String getCustomerCode() {
61	        return this.customerCode;
62	    }
63	
64	    public void setCustomerCode(String customerCode) {
65	        this.customerCode = customerCode;
66	    }
67	
68	    /** Assign the customer code '<CITY3>-<LAST3>-<NNNN>' for the given per-city sequence number. */
69	    public void assignCustomerCode(int sequence) {
70	        this.customerCode = getCity().substring(0, 3).toUpperCase() + "-"
71	            + getLastName().substring(0, 3).toUpperCase() + String.format("-%04d", sequence);
72	    }
73	
74	    @Transient
75	    private String householdId;
76	
77	    public String getHouseholdId() {
78	        return this.householdId;
79	    }
80	
81	    public void setHouseholdId(String householdId) {
82	        this.householdId = householdId;
83	    }
84	
85	    @Transient
86	    private Integer namesakeCount;
87	
88	    public Integer getNamesakeCount() {
89	        return this.namesakeCount;
90	    }
91	
92	    public void setNamesakeCount(Integer namesakeCount) {
93	        this.namesakeCount = namesakeCount;
94	    }
95	
96	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
97	    private Set<Pet> pets;
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    /** Store the email lower-cased so it is persisted and returned normalised. */
104	    public void setEmail(String email) {
105	        this.email = (email == null) ? null : email.toLowerCase();
106	    }
107	
108	    public LocalDate getRegistrationDate() {
109	        return this.registrationDate;
110	    }
111	
112	    public void setRegistrationDate(LocalDate registrationDate) {
113	        this.registrationDate = registrationDate;
114	    }
115	
116	    /** Default a missing registration date to the server's current date on create. */
117	    @PrePersist
118	    protected void ensureRegistrationDate() {
119	        if (this.registrationDate == null) {
120	            this.registrationDate = LocalDate.now();
121	        }
122	    }
123	
124	    public String getAddress() {
125	        return this.address;
126	    }
127	
128	    public void setAddress(String address) {
129	        this.address = address;
130	    }
131	
132	    public String getCity() {
133	        return this.city;
134	    }
135	
136	    public void setCity(String city) {
137	        this.city = city;
138	    }
139	
140	    public String getTelephone() {
141	        return this.telephone;
142	    }
143	
144	    public void setTelephone(String telephone) {
145	        this.telephone = telephone;
146	    }
147	
148	    protected Set<Pet> getPetsInternal() {
149	        if (this.pets == null) {
150	            this.pets = new HashSet<>();
151	        }
152	        return this.pets;
153	    }
154	
155	    protected void setPetsInternal(Set<Pet> pets) {
156	        this.pets = pets;
157	    }
158	
159	    public List<Pet> getPets() {
160	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
161	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
162	        return Collections.unmodifiableList(sortedPets);
163	    }
164	
165	    public void setPets(List<Pet> pets) {
166	        this.pets = new HashSet<>(pets);
167	    }
168	
169	    public void addPet(Pet pet) {
170	        getPetsInternal().add(pet);
171	        pet.setOwner(this);
172	    }
173	
174	    /**
175	     * Return the Pet with the given name, or null if none found for this Owner.
176	     *
177	     * @param name to test
178	     * @return true if pet name is already in use
179	     */
180	    public Pet getPet(String name) {
181	        return getPet(name, false);
182	    }
183	
184	    /**
185	     * Return the Pet with the given name, or null if none found for this Owner.
186	     *
187	     * @param name to test
188	     * @return true if pet name is already in use
189	     */
190	    public Pet getPet(String name, boolean ignoreNew) {
191	        name = name.toLowerCase();
192	        for (Pet pet : getPetsInternal()) {
193	            if (!ignoreNew || !pet.isNew()) {
194	                String compName = pet.getName();
195	                compName = compName.toLowerCase();
196	                if (compName.equals(name)) {
197	                    return pet;
198	                }
199	            }
200	        }
201	        return null;
202	    }
203	
204	    public Pet getPet(Integer petId) {
205	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
206	    }
207	
208	    @Override
209	    public String toString() {
210	        return new ToStringCreator(this)
211	
212	            .append("id", this.getId())
213	            .append("new", this.isNew())
214	            .append("lastName", this.getLastName())
215	            .append("firstName", this.getFirstName())
216	            .append("address", this.address)
217	            .append("city", this.city)
218	            .append("telephone", this.telephone)
219	            .toString();
220	    }
221	}
