1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Counts owners already registered in a candidate's city, compared case-insensitively.
9	 * Used to derive the per-city sequence in the customerCode.
10	 */
11	final class CityCodes {
12	
13	    private CityCodes() {
14	    }
15	
16	    /** Lower-case a value for comparison, treating null as empty. */
17	    private static String normalize(String value) {
18	        return value == null ? "" : value.toLowerCase();
19	    }
20	
21	    /** Count existing owners sharing the candidate's city. */
22	    static int count(Collection<Owner> existing, Owner candidate) {
23	        String city = normalize(candidate.getCity());
24	        return (int) existing.stream().filter(o -> normalize(o.getCity()).equals(city)).count();
25	    }
26	}
