1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.Collection;
5	import java.util.UUID;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Detects owners that share a household, i.e. carry the same last name and the
11	 * same address compared case-insensitively with collapsed whitespace.
12	 */
13	final class Households {
14	
15	    private Households() {
16	    }
17	
18	    /** Trim, collapse internal whitespace and lower-case a value for comparison. */
19	    private static String normalize(String value) {
20	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
21	    }
22	
23	    /** True when an existing owner has the candidate's last name and address. */
24	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
25	        String lastName = normalize(candidate.getLastName());
26	        String address = normalize(candidate.getAddress());
27	        return existing.stream().anyMatch(o ->
28	            normalize(o.getLastName()).equals(lastName) && normalize(o.getAddress()).equals(address));
29	    }
30	
31	    /**
32	     * The stable household id to assign to an owner, or {@code null} when it is not
33	     * joining one. Derived from the normalized last name and address, so every owner
34	     * that joins the same household is given the same identifier.
35	     */
36	    static String householdId(Collection<Owner> existing, boolean sharesHousehold, Owner candidate) {
37	        if (!sharesHousehold || !isDuplicate(existing, candidate)) {
38	            return null;
39	        }
40	        String key = normalize(candidate.getLastName()) + "\n" + normalize(candidate.getAddress());
41	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
42	    }
43	}
