1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Counts owners that are namesakes, i.e. carry the same first name and last name
9	 * compared case-insensitively.
10	 */
11	final class Namesakes {
12	
13	    private Namesakes() {
14	    }
15	
16	    /** Lower-case a value for comparison, treating null as empty. */
17	    private static String normalize(String value) {
18	        return value == null ? "" : value.toLowerCase();
19	    }
20	
21	    /** Count existing owners sharing the candidate's first and last name. */
22	    static int count(Collection<Owner> existing, Owner candidate) {
23	        String firstName = normalize(candidate.getFirstName());
24	        String lastName = normalize(candidate.getLastName());
25	        return (int) existing.stream().filter(o ->
26	            normalize(o.getFirstName()).equals(firstName) && normalize(o.getLastName()).equals(lastName)).count();
27	    }
28	}
