1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.util.Addresses;
10	import org.springframework.samples.petclinic.util.E164;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials", source = "initials")
26	    @Mapping(target = "membershipNumber", expression = "java((owner.getCustomerCode() == null || owner.getRegistrationDate() == null) ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipTier", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank() && java.lang.Integer.valueOf(0).equals(owner.getNamesakeCount())) ? \"SILVER\" : \"BRONZE\")")
28	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.Localities.regionOf(owner.getCity()))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    Owner toOwner(OwnerDto ownerDto);
32	
33	    @Mapping(target = "id", ignore = true)
34	    @Mapping(target = "pets", ignore = true)
35	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
36	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
37	    Owner toOwner(OwnerFieldsDto ownerDto);
38	
39	    /** Store the telephone in E.164 form (see {@link E164#toE164}). */
40	    @Named("normalizeTelephone")
41	    default String normalizeTelephone(String telephone) {
42	        return E164.toE164(telephone);
43	    }
44	
45	    /** Store the address in normalized form (see {@link Addresses#normalize}). */
46	    @Named("normalizeAddress")
47	    default String normalizeAddress(String address) {
48	        return Addresses.normalize(address);
49	    }
50	
51	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
52	
53	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
54	
